const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point([-121.8863, 37.3361]); // San Jose, CA
    const areaOfInterest = point.buffer(30000); // 30km buffer
    const dateRangeJune = ee.DateRange('2020-06-01', '2020-06-30');
    const dateRangeAugust = ee.DateRange('2020-08-20', '2020-08-31');

    // 2. Data Acquisition & Pre-processing
    function getS2Collection(dateRange, geometry) {
        return ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
            .filterBounds(geometry)
            .filterDate(dateRange)
            // Pre-filter to get less cloudy scenes.
            .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));
    }

    // Cloud masking function for Sentinel-2
    function maskS2Clouds(image) {
        const qa = image.select('QA60');
        const cloudBitMask = 1 << 10;
        const cirrusBitMask = 1 << 11;
        const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
            .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
        return image.updateMask(mask).divide(10000)
            .select("B8", "B12")
            .copyProperties(image, ["system:time_start"]);
    }

    // NBR calculation function
    const addNBR = function(image) {
        return image.normalizedDifference(['B8', 'B12']).rename('NBR');
    };

    // 3. Processing
    const collectionJune = getS2Collection(dateRangeJune, areaOfInterest);
    const collectionAugust = getS2Collection(dateRangeAugust, areaOfInterest);

    const juneSize = collectionJune.size().getInfo();
    const augustSize = collectionAugust.size().getInfo();

    console.log(`Image count June 2020: ${juneSize}`);
    console.log(`Image count August 2020: ${augustSize}`);

    if (juneSize === 0 || augustSize === 0) {
        console.log("Evidence: One or both time periods have no images available.");
        console.log("A"); // The SCU Lightning Complex fire started in August. It is expected that June had no burns. This is a valid zero.
        return;
    }

    // Create composites and calculate NBR
    const imageJune = collectionJune.map(maskS2Clouds).median();
    const imageAugust = collectionAugust.map(maskS2Clouds).median();

    const nbrJune = addNBR(imageJune);
    const nbrAugust = addNBR(imageAugust);

    // Define a burn threshold. Low NBR indicates burned areas.
    const burnThreshold = 0.1;
    const burnedJune = nbrJune.lt(burnThreshold);
    const burnedAugust = nbrAugust.lt(burnThreshold);

    // Calculate pixel counts
    const scale = 1000;
    const pixelArea = ee.Image.pixelArea();

    const burnedAreaJune = burnedJune.multiply(pixelArea).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: areaOfInterest,
        scale: scale,
        maxPixels: 1e9
    }).get('NBR');

    const burnedAreaAugust = burnedAugust.multiply(pixelArea).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: areaOfInterest,
        scale: scale,
        maxPixels: 1e9
    }).get('NBR');

    const burnedAreaJuneMeters = ee.Number(burnedAreaJune).getInfo();
    const burnedAreaAugustMeters = ee.Number(burnedAreaAugust).getInfo();

    if (burnedAreaJuneMeters === null || burnedAreaAugustMeters === null) {
        console.log("Evidence: Failed to calculate burned area for one or both periods.");
        console.log("C3");
        return;
    }

    const burnedAreaJuneSqKm = burnedAreaJuneMeters / 1e6;
    const burnedAreaAugustSqKm = burnedAreaAugustMeters / 1e6;

    // 4. Validation & Final Answer
    console.log(`Evidence: Burned Area (June 2020): ${burnedAreaJuneSqKm.toFixed(2)} sq km`);
    console.log(`Evidence: Burned Area (August 2020): ${burnedAreaAugustSqKm.toFixed(2)} sq km`);

    if (burnedAreaAugustSqKm > burnedAreaJuneSqKm) {
        console.log("Conclusion: Burn scars expanded significantly between June and August 2020.");
        console.log("A");
    } else {
        console.log("Conclusion: Burn scars did not expand between June and August 2020.");
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject, (e) => {
            console.error('Authentication error: ' + e);
            process.exit(1);
        });
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject, (e) => {
            console.error('Initialization error: ' + e);
            process.exit(1);
        });
    });
    try {
        await runAnalysis();
    } catch (e) {
        console.error(`Unhandled error: ${e}`);
        console.log("D");
        process.exit(1);
    }
}

initEE();
